package tests;
import Code.*;import Service.*;import ImplementationDB.*;
import java.math.*;import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import static tests.TestKit.*;import static ImplementationDB.Jdbc.*;
/** DESTRUCTIVE FIXTURE CREATION ONLY ON A DEDICATED *_Test DATABASE.
 * Opt in with DIENMAY_IT_ALLOW_WRITES=YES; apply schema first, do not install demo.
 * Tests retain their audit trail. Drop the entire throwaway DB yourself after review. */
public final class SqlServerIT {
    private static final String PASSWORD="IT-only-Secret!2026";
    private static SQL db;private static InventorySystem app;private static AuthService.Session manager,cashier,warehouse;
    private static String prefix;private static long category,brand,vendor,product,customer,serialProduct;
    private static Sale initialSale,serialSale;private static long warranty,claim;
    private static long scalar(String sql,Object...args)throws SQLException{return db.read(c->{try(PreparedStatement s=statement(c,sql,args);ResultSet r=s.executeQuery()){r.next();return r.getLong(1);}});}
    private static BigDecimal decimal(String sql,Object...args)throws SQLException{return db.read(c->{try(PreparedStatement s=statement(c,sql,args);ResultSet r=s.executeQuery()){r.next();return r.getBigDecimal(1);}});}
    private static Item make(long id,int revision,String sku,boolean serial,int months,BigDecimal price){return new Item(id,sku,"000"+sku,"Sản phẩm kiểm thử "+sku,category,brand,"Danh mục","Hãng","M","Dữ liệu kiểm thử",Money.of("60"),price,months,serial,true,2,0,0,revision);}
    private static ItemQuantity line(long product,int qty,List<String> serials)throws SQLException{Item item=app.getStore().catalog().get(manager,product);return new ItemQuantity(item.id(),item.sku(),item.name(),item.sellingPrice(),qty,serials);}
    private static SaleRequest request(long product,int qty,List<String> serials)throws SQLException{return new SaleRequest(UUID.randomUUID(),customer,"CASH",Money.ZERO,"",Money.ZERO,List.of(line(product,qty,serials)));}
    private static InventoryService.Request receive(long id,int qty,String...serials){return new InventoryService.Request(UUID.randomUUID(),id,qty,List.of(serials),prefix+" phiếu nhập",vendor,Money.of("60"),null,"KHO");}
    private static InventoryService.Request transfer(long id,int qty,String...serials){return new InventoryService.Request(UUID.randomUUID(),id,qty,List.of(serials),prefix+" chuyển",null,Money.ZERO,"KHO","QUAY");}
    private static int qty(long id,String location)throws SQLException{return (int)scalar("SELECT Quantity FROM dm.Stock WHERE ProductId=? AND Location=?",id,location);}
    private static List<Object> concurrently(Callable<Object> a,Callable<Object> b)throws Exception{
        ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);
        try{Future<Object> fa=pool.submit(()->{start.await();try{return a.call();}catch(Exception e){return e;}}),fb=pool.submit(()->{start.await();try{return b.call();}catch(Exception e){return e;}});start.countDown();return List.of(fa.get(45,TimeUnit.SECONDS),fb.get(45,TimeUnit.SECONDS));}finally{pool.shutdownNow();}
    }
    public static void main(String[] args)throws Exception{
        if(!"YES".equals(System.getenv("DIENMAY_IT_ALLOW_WRITES"))){System.out.println("NOT RUN | SQL Server integration requires an explicitly opted-in *_Test database (DIENMAY_IT_ALLOW_WRITES=YES).");return;}
        db=new SQL();String dbName=db.read(c->{try(PreparedStatement s=statement(c,"SELECT DB_NAME()");ResultSet r=s.executeQuery()){r.next();return r.getString(1);}});
        if(!dbName.endsWith("_Test"))throw new SecurityException("Refusing integration writes: database name must end with _Test. Actual: "+dbName);
        db.checkConnection();app=new InventorySystem(db);prefix="IT"+UUID.randomUUID().toString().replace("-","").substring(0,10);
        for(Role role:Role.values()){String hash=Passwords.hash(PASSWORD.toCharArray());db.transaction(c->{insert(c,"INSERT dm.Employees(UserName,FullName,PasswordHash,Role,MustChange) OUTPUT INSERTED.Id VALUES(?,?,?,?,0)",prefix+role.name(),prefix+role.name(),hash,role.name());return null;});}
        manager=app.auth.login(prefix+"MANAGER",PASSWORD.toCharArray());cashier=app.auth.login(prefix+"CASHIER",PASSWORD.toCharArray());warehouse=app.auth.login(prefix+"WAREHOUSE",PASSWORD.toCharArray());
        category=app.getStore().catalog().saveLookup(manager,"category",null,prefix+" Danh mục");brand=app.getStore().catalog().saveLookup(manager,"brand",null,prefix+" Hãng");
        vendor=app.people.saveVendor(manager,null,prefix+" Nhà cung cấp","0900000001","Địa chỉ test",true);customer=app.people.saveCustomer(cashier,null,prefix+" Khách hàng","0900001234","Test");
        product=app.getStore().catalog().save(manager,make(0,0,prefix+"SKU",false,12,Money.of("100")));
        TestKit t=new TestKit();
        t.test("A: DB role from authentication",()->{equal(Role.MANAGER,manager.role());equal(Role.CASHIER,cashier.role());equal(Role.WAREHOUSE,warehouse.role());});
        t.test("A: wrong password refused",()->throwsType(SecurityException.class,()->app.auth.login(prefix+"CASHIER","wrong-password-2026".toCharArray())));
        t.test("A: cashier cannot create product",()->throwsType(SecurityException.class,()->app.getStore().catalog().save(cashier,make(0,0,prefix+"ILLEGAL",false,0,Money.of("10")))));
        t.test("A: warehouse cannot assign roles",()->throwsType(SecurityException.class,()->app.people.saveEmployee(warehouse,null,prefix+"ILLEGAL","Illegal","",Role.MANAGER,true,PASSWORD.toCharArray())));
        t.test("B: receive 10 and retry the SAME inventory request",()->{InventoryService.Request r=receive(product,10);app.getWarehouse().inventory().receive(warehouse,r);equal(10,qty(product,"KHO"));app.getWarehouse().inventory().receive(warehouse,r);equal(10,qty(product,"KHO"));});
        t.test("B: transfer adds to destination rather than overwriting",()->{app.getWarehouse().inventory().transfer(warehouse,transfer(product,4));app.getWarehouse().inventory().transfer(warehouse,transfer(product,2));equal(4,qty(product,"KHO"));equal(6,qty(product,"QUAY"));});
        t.test("C: barcode lookup preserves leading zeros",()->equal(product,app.getStore().catalog().find(cashier,"000"+prefix+"SKU").id()));
        final SaleRequest first=request(product,2,List.of());
        t.test("B/C: sell 2 commits invoice/details/stock/warranty",()->{initialSale=app.getStore().sales().checkout(cashier,first);equal(4,qty(product,"QUAY"));equal(Money.of("200"),initialSale.total());equal(1,initialSale.items().size());equal(2,initialSale.items().get(0).quantity());equal(1L,scalar("SELECT COUNT(*) FROM dm.Invoices WHERE RequestId=?",first.requestId()));equal(2L,scalar("SELECT SUM(w.CoveredQuantity) FROM dm.Warranties w JOIN dm.InvoiceDetails d ON d.Id=w.DetailId WHERE d.InvoiceId=?",initialSale.id()));});
        t.test("C: same checkout request returns same invoice without extra stock movement",()->{Sale repeat=app.getStore().sales().checkout(cashier,first);equal(initialSale.id(),repeat.id());equal(4,qty(product,"QUAY"));});
        t.test("C: changed payload with reused request ID refused",()->{SaleRequest changed=new SaleRequest(first.requestId(),customer,"CASH",Money.ZERO,"",Money.ZERO,List.of(line(product,1,List.of())));throwsType(SecurityException.class,()->app.getStore().sales().checkout(cashier,changed));equal(4,qty(product,"QUAY"));});
        t.test("B: two concurrent oversubscribing sales never create negative stock",()->{SaleRequest a=request(product,3,List.of()),b=request(product,3,List.of());List<Object> results=concurrently(()->app.getStore().sales().checkout(cashier,a),()->app.getStore().sales().checkout(cashier,b));equal(1L,results.stream().filter(Sale.class::isInstance).count());equal(1,qty(product,"QUAY"));});
        t.test("C: concurrent duplicate requests create exactly one invoice",()->{SaleRequest same=request(product,1,List.of());List<Object> result=concurrently(()->app.getStore().sales().checkout(cashier,same),()->app.getStore().sales().checkout(cashier,same));check(result.get(0) instanceof Sale&&result.get(1) instanceof Sale,"Both retries must resolve: "+result);equal(((Sale)result.get(0)).id(),((Sale)result.get(1)).id());equal(0,qty(product,"QUAY"));equal(1L,scalar("SELECT COUNT(*) FROM dm.Invoices WHERE RequestId=?",same.requestId()));});
        t.test("B: additional transfer restores only physical stock",()->{app.getWarehouse().inventory().transfer(warehouse,transfer(product,4));equal(0,qty(product,"KHO"));equal(4,qty(product,"QUAY"));});
        for(String phase:List.of("AFTER_INVOICE","AFTER_STOCK","BEFORE_COMMIT"))t.test("C: SQL rollback injected at "+phase,()->{
            long movements=scalar("SELECT COUNT(*) FROM dm.StockMovements WHERE ProductId=?",product),warranties=scalar("SELECT COUNT(*) FROM dm.Warranties");SaleRequest r=request(product,1,List.of());
            SalesService failing=new SalesService(db,app.auth,step->{if(step.equals(phase))throw new SQLException("INJECTED "+phase);});
            throwsType(SQLException.class,()->failing.checkout(cashier,r));equal(4,qty(product,"QUAY"));equal(0L,scalar("SELECT COUNT(*) FROM dm.Invoices WHERE RequestId=?",r.requestId()));equal(movements,scalar("SELECT COUNT(*) FROM dm.StockMovements WHERE ProductId=?",product));equal(warranties,scalar("SELECT COUNT(*) FROM dm.Warranties"));equal(null,app.getStore().sales().resolve(cashier,r));
        });
        t.test("B/C: overstock rollback leaves no invoice",()->{SaleRequest r=request(product,99,List.of());throwsType(IllegalArgumentException.class,()->app.getStore().sales().checkout(cashier,r));equal(4,qty(product,"QUAY"));equal(0L,scalar("SELECT COUNT(*) FROM dm.Invoices WHERE RequestId=?",r.requestId()));});
        t.test("C: changed price requires new confirmation",()->{SaleRequest r=request(product,1,List.of());Item i=app.getStore().catalog().get(manager,product);app.getStore().catalog().save(manager,make(product,i.revision(),i.sku(),false,12,Money.of("101")));throwsType(IllegalArgumentException.class,()->app.getStore().sales().checkout(cashier,r));equal(4,qty(product,"QUAY"));i=app.getStore().catalog().get(manager,product);app.getStore().catalog().save(manager,make(product,i.revision(),i.sku(),false,12,Money.of("100")));});
        t.test("C: promotion changed after quote is rejected atomically",()->{LocalDate day=db.read(Jdbc::now).atZone(Validation.ZONE).toLocalDate();String code=prefix+"PROMO";long promotion=app.promotions.save(manager,null,code,"Promo test",day.minusDays(1),day.plusDays(1),Money.of("10"),true);List<ItemQuantity> lines=List.of(line(product,1,List.of()));SalesService.Quote q=app.getStore().sales().quote(cashier,lines,code,Money.ZERO);SaleRequest r=new SaleRequest(UUID.randomUUID(),null,"CASH",Money.ZERO,code,q.discount(),lines);app.promotions.save(manager,promotion,code,"Changed",day.minusDays(1),day.plusDays(1),Money.of("20"),true);throwsType(IllegalArgumentException.class,()->app.getStore().sales().checkout(cashier,r));equal(4,qty(product,"QUAY"));});
        t.test("D: serialized receiving and transfer",()->{serialProduct=app.getStore().catalog().save(manager,make(0,0,prefix+"SER",true,12,Money.of("1000")));app.getWarehouse().inventory().receive(warehouse,receive(serialProduct,2,prefix+"S1",prefix+"S2"));equal(2,qty(serialProduct,"KHO"));app.getWarehouse().inventory().transfer(warehouse,transfer(serialProduct,2,prefix+"S1",prefix+"S2"));equal(2,qty(serialProduct,"QUAY"));});
        t.test("D: duplicate serial in receiving rolls back stock",()->{throwsType(SQLException.class,()->app.getWarehouse().inventory().receive(warehouse,receive(serialProduct,1,prefix+"S1")));equal(0,qty(serialProduct,"KHO"));equal(2,qty(serialProduct,"QUAY"));});
        t.test("D: sold serial links to invoice and 12-month warranty",()->{serialSale=app.getStore().sales().checkout(cashier,request(serialProduct,1,List.of(prefix+"S1")));equal(1,qty(serialProduct,"QUAY"));warranty=scalar("SELECT w.Id FROM dm.Warranties w JOIN dm.InvoiceDetails d ON d.Id=w.DetailId WHERE d.InvoiceId=?",serialSale.id());equal(12L,scalar("SELECT WarrantyMonths FROM dm.Warranties WHERE Id=?",warranty));equal(1L,scalar("SELECT COUNT(*) FROM dm.Warranties w JOIN dm.InvoiceDetails d ON d.Id=w.DetailId JOIN dm.ProductUnits u ON u.Id=w.UnitId WHERE w.Id=? AND d.InvoiceId=? AND u.Serial=? AND w.EndDate=DATEADD(month,12,w.StartDate)",warranty,serialSale.id(),prefix+"S1"));});
        t.test("D: the same sold serial cannot be sold again",()->{SaleRequest duplicate=request(serialProduct,1,List.of(prefix+"S1"));throwsType(IllegalArgumentException.class,()->app.getStore().sales().checkout(cashier,duplicate));equal(1,qty(serialProduct,"QUAY"));equal(0L,scalar("SELECT COUNT(*) FROM dm.Invoices WHERE RequestId=?",duplicate.requestId()));});
        t.test("D: later product policy changes do not rewrite old warranty",()->{Item i=app.getStore().catalog().get(manager,serialProduct);app.getStore().catalog().save(manager,make(serialProduct,i.revision(),i.sku(),true,24,i.sellingPrice()));equal(12L,scalar("SELECT WarrantyMonths FROM dm.Warranties WHERE Id=?",warranty));});
        t.test("D: search warranty by invoice, serial and customer phone",()->{check(!app.warranties.search(cashier,serialSale.code()).isEmpty(),"Invoice search failed");check(!app.warranties.search(cashier,prefix+"S1").isEmpty(),"Serial search failed");check(!app.warranties.search(cashier,"0900001234").isEmpty(),"Phone search failed");});
        t.test("D: expired warranty may still be received (test fixture only)",()->{
            LocalDate today=db.read(Jdbc::now).atZone(Validation.ZONE).toLocalDate();
            db.transaction(c->{update(c,"UPDATE dm.Warranties SET StartDate=?,EndDate=? WHERE Id=?",today.minusYears(2),today.minusYears(1),warranty);return null;});
            check(app.warranties.search(cashier,serialSale.code()).stream().anyMatch(row->"Hết hạn".equals(row.get("Hiệu lực"))),"Expired status missing");
            long expiredClaim=app.warranties.receive(cashier,warranty,"Fixture: tiếp nhận dù đã hết hạn");
            equal(1L,scalar("SELECT COUNT(*) FROM dm.WarrantyClaims WHERE Id=?",expiredClaim));
        });
        t.test("D: cashier may receive claim but not change manager-only status",()->{claim=app.warranties.receive(cashier,warranty,"Màn hình lỗi — fixture test");throwsType(SecurityException.class,()->app.warranties.transition(cashier,claim,"RECEIVED","PROCESSING","Not permitted"));equal(1L,scalar("SELECT COUNT(*) FROM dm.ClaimHistory WHERE ClaimId=?",claim));});
        t.test("D: manager transitions preserve complete history",()->{app.warranties.transition(manager,claim,"RECEIVED","PROCESSING","Đang kiểm tra");app.warranties.transition(manager,claim,"PROCESSING","COMPLETED","Đã hoàn tất");equal(3L,scalar("SELECT COUNT(*) FROM dm.ClaimHistory WHERE ClaimId=?",claim));equal(1L,scalar("SELECT COUNT(*) FROM dm.WarrantyClaims WHERE Id=? AND CompletedAt IS NOT NULL AND Status='COMPLETED'",claim));});
        t.test("D: terminal claim cannot be reopened by invalid transition",()->{throwsType(IllegalArgumentException.class,()->app.warranties.transition(manager,claim,"COMPLETED","PROCESSING","Invalid"));equal(3L,scalar("SELECT COUNT(*) FROM dm.ClaimHistory WHERE ClaimId=?",claim));});
        t.test("C/D: joining multiple serials never duplicates invoice quantity",()->{app.getWarehouse().inventory().receive(warehouse,receive(serialProduct,2,prefix+"S3",prefix+"S4"));app.getWarehouse().inventory().transfer(warehouse,transfer(serialProduct,2,prefix+"S3",prefix+"S4"));Sale sale=app.getStore().sales().checkout(cashier,request(serialProduct,2,List.of(prefix+"S2",prefix+"S3")));Sale reloaded=app.getStore().sales().load(cashier,sale.id());equal(1,reloaded.items().size());equal(2,reloaded.items().get(0).quantity());equal(2L,scalar("SELECT COUNT(*) FROM dm.Warranties w JOIN dm.InvoiceDetails d ON d.Id=w.DetailId WHERE d.InvoiceId=?",sale.id()));});
        t.test("A: locking employee revokes existing session",()->{app.people.saveEmployee(manager,warehouse.employeeId(),prefix+"WAREHOUSE",prefix+"WAREHOUSE","",Role.WAREHOUSE,false,null);throwsType(SecurityException.class,()->app.getStore().catalog().search(warehouse,""));app.people.saveEmployee(manager,warehouse.employeeId(),prefix+"WAREHOUSE",prefix+"WAREHOUSE","",Role.WAREHOUSE,true,null);warehouse=app.auth.login(prefix+"WAREHOUSE",PASSWORD.toCharArray());});
        t.test("A: initial password change required and old session revoked",()->{String user=prefix+"NEW";app.people.saveEmployee(manager,null,user,"New cashier","",Role.CASHIER,true,PASSWORD.toCharArray());AuthService.Session firstSession=app.auth.login(user,PASSWORD.toCharArray());check(firstSession.mustChange(),"MustChange not set");throwsType(SecurityException.class,()->app.getStore().catalog().search(firstSession,""));AuthService.Session changed=app.auth.changePassword(firstSession,PASSWORD.toCharArray(),"Different-secret!2026".toCharArray());check(!changed.mustChange(),"MustChange not cleared");throwsType(SecurityException.class,()->app.getStore().catalog().search(firstSession,""));check(!app.getStore().catalog().search(changed,prefix).isEmpty(),"New session rejected");app.auth.logout(changed);});
        t.test("E: revenue/count exactly match invoice headers, not detail join",()->{LocalDate day=db.read(Jdbc::now).atZone(Validation.ZONE).toLocalDate();Map<String,Object> summary=app.reports.report(manager,"summary",day,day).get(0);equal(scalar("SELECT COUNT_BIG(*) FROM dm.Invoices WHERE SoldAt>=? AND SoldAt<?",Validation.start(day),Validation.start(day.plusDays(1))),((Number)summary.get("Số hóa đơn")).longValue());BigDecimal total=decimal("SELECT COALESCE(SUM(Total),0) FROM dm.Invoices WHERE SoldAt>=? AND SoldAt<?",Validation.start(day),Validation.start(day.plusDays(1)));check(total.compareTo((BigDecimal)summary.get("Doanh thu thuần"))==0,"Revenue mismatch");});
        t.test("B/C/D: fresh service graph reloads committed stock, invoice and warranty",()->{InventorySystem reopened=new InventorySystem(new SQL());AuthService.Session session=reopened.auth.login(prefix+"CASHIER",PASSWORD.toCharArray());Sale loaded=reopened.getStore().sales().load(session,initialSale.id());equal(initialSale,loaded);equal(4,reopened.getStore().catalog().get(session,product).counterQuantity());check(!reopened.warranties.search(session,serialSale.code()).isEmpty(),"Warranty lost after reopening");});
        t.test("B/E: stock exactly reconciles with movement ledger",()->equal(0L,scalar("SELECT COUNT(*) FROM (SELECT s.ProductId,s.Location,s.Quantity,COALESCE(SUM(CONVERT(bigint,m.Delta)),0) AS Ledger FROM dm.Stock s LEFT JOIN dm.StockMovements m ON m.ProductId=s.ProductId AND m.Location=s.Location WHERE s.ProductId IN(?,?) GROUP BY s.ProductId,s.Location,s.Quantity HAVING s.Quantity<>COALESCE(SUM(CONVERT(bigint,m.Delta)),0)) x",product,serialProduct)));
        t.finish();System.out.println("FIXTURES RETAINED | prefix="+prefix+" | database="+dbName);
        System.out.println("NOT RUN | Physical scanner and physical printer still require manual acceptance.");
    }
}
